// Import of required libraries
import { test, expect, SkyrampClient, getResponseValue } from '@skyramp/skyramp';
import { createOwner, deleteOwnerPets, deleteOwner } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const ownersPostRequestBody: string = `{
        "address": "2 Reject Way",
        "city": "Madison",
        "firstName": "Rejection",
        "lastName": "Owner",
        "telephone": "6085550222"
    }`;

    const ownersPostResponse = await createOwner(client, ownersPostRequestBody);
    expect(ownersPostResponse.statusCode, 'status code').toBe(201);
    expect(Number(getResponseValue(ownersPostResponse, "id")), 'id').toBeGreaterThan(0);
    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Rejection");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Owner");
    expect(getResponseValue(ownersPostResponse, "address"), 'address').toBe("2 Reject Way");
    expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe("Madison");
    expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone').toBe("6085550222");
    expect((getResponseValue(ownersPostResponse, "pets") as unknown[]).length, 'pets length').toBe(0);

    const ownerId = getResponseValue(ownersPostResponse, "id");

    const ownersPetsDeleteResponse = await deleteOwnerPets(client, ownerId);
    expect(ownersPetsDeleteResponse.statusCode, 'status code').toBe(204);

    const owners999999PetsDeleteResponse = await deleteOwnerPets(client, 999999, 404);
    expect(owners999999PetsDeleteResponse.statusCode, 'status code').toBe(404);

    const petsDeleteResponse = await deleteOwnerPets(client, -1, 400);
    expect(petsDeleteResponse.statusCode, 'status code').toBe(400);

    const ownersOwnersDeleteResponse = await deleteOwner(client, ownerId);
    expect(ownersOwnersDeleteResponse.statusCode, 'status code').toBe(204);
});
